"""連 PCCES 本機 SQL Server 的唯讀連線。

只准 SELECT：每一句查詢送出前都過 check_select_only。連線字串的 readonly 與
ApplicationIntent=ReadOnly 擋不擋得住寫入沒驗過（驗要真的寫一次，專案規則不准），
所以防線放在這道檢查，tests\\test_db_readonly.py 守它。
"""

from __future__ import annotations

import os
import re
from typing import Any

try:
    import pyodbc
except ImportError:  # 沒裝 pyodbc 時 XML 工具照樣要能用，連線時才報
    pyodbc = None

DEFAULT_SERVER = r".\SQLEXPRESS"
DATABASE = "Pcces"
# 依序挑這台有的第一個。SQL 2022 Express 安裝時會帶 Driver 17；裝 PCCES 附的 SQL 2014 只有 Native Client 11；
# 「SQL Server」是 Windows 內建、每台都有。三者讀 Pcces 逐格相同（tools\pcces_db\driver_probe.py，2026-11-20）。
# 不列 Driver 18：它預設 Encrypt=yes，本機自簽憑證會連不上。
DRIVERS = ("ODBC Driver 17 for SQL Server", "SQL Server Native Client 11.0", "SQL Server")
# 本機連線正常時瞬間完成；找不到執行個體時實測等滿這段才失敗，預設 15 秒太久
LOGIN_TIMEOUT = 5
QUERY_TIMEOUT = 30


class DbUnavailable(Exception):
    """環境問題：沒驅動、服務沒開、帳號進不了資料庫、資料表欄位不符。訊息寫使用者的下一步。"""


class ReadOnlyViolation(ValueError):
    """查詢不是單一 SELECT。只會是程式寫錯，不是使用者能改的參數。"""


def server_name() -> str:
    """SQL Server 執行個體；PCCES 手冊規定叫 .\\SQLEXPRESS，別的名稱用環境變數 PCX_DB_SERVER 指定。"""
    return os.environ.get("PCX_DB_SERVER") or DEFAULT_SERVER


def _code_only(sql: str) -> str:
    """把字串常值換成 ''、註解換成空白，只留程式碼，關鍵字檢查才不會被字串或註解騙過。"""
    out: list[str] = []
    i, n = 0, len(sql)
    while i < n:
        c = sql[i]
        if c == "'":
            j = i + 1
            while j < n:
                if sql[j] == "'":
                    if j + 1 < n and sql[j + 1] == "'":
                        j += 2
                        continue
                    break
                j += 1
            out.append("''")
            i = j + 1
        elif sql.startswith("--", i):
            j = sql.find("\n", i)
            i = n if j < 0 else j
            out.append(" ")
        elif sql.startswith("/*", i):
            j = sql.find("*/", i + 2)
            i = n if j < 0 else j + 2
            out.append(" ")
        else:
            out.append(c)
            i += 1
    return "".join(out)


# SELECT … INTO 會建表、WITH … DELETE 會刪資料，所以只看開頭不夠
_WRITE_WORDS = re.compile(
    r"\b(INSERT|UPDATE|DELETE|MERGE|DROP|ALTER|CREATE|TRUNCATE|EXEC|EXECUTE|INTO|GRANT|REVOKE|DENY"
    r"|BACKUP|RESTORE|DBCC|DECLARE|SET|USE|OPENROWSET|OPENQUERY|OPENDATASOURCE|WAITFOR|SHUTDOWN"
    r"|KILL|BULK|SP_\w+|XP_\w+)\b",
    re.IGNORECASE,
)


def check_select_only(sql: str) -> None:
    body = _code_only(sql)
    head = body.lstrip().upper()
    if not (head.startswith("SELECT") or head.startswith("WITH")):
        raise ReadOnlyViolation("只准 SELECT：查詢要以 SELECT 或 WITH 開頭")
    if ";" in body:
        raise ReadOnlyViolation("只准單一 SELECT：不能用分號接第二句")
    m = _WRITE_WORDS.search(body)
    if m:
        raise ReadOnlyViolation(f"只准 SELECT：查詢裡有 {m.group(0)}")


def driver_name() -> str:
    """要用的 ODBC 驅動：環境變數 PCX_DB_DRIVER 指定的優先（測試用它強制走內建驅動），否則挑 DRIVERS 裡這台有的第一個。"""
    forced = os.environ.get("PCX_DB_DRIVER")
    if forced:
        return forced
    have = set(pyodbc.drivers()) if pyodbc is not None else set()
    return next((d for d in DRIVERS if d in have), DRIVERS[0])


def _explain(state: str, server: str, driver: str) -> str:
    if state == "IM002":
        return f"這台電腦沒有 ODBC 驅動「{driver}」，資料庫工具連不上；請改用匯出的 XML。"
    if state in ("08001", "08S01", "HYT00", "HYT01"):
        return (f"連不到 SQL Server {server}：服務沒開，或這台沒裝 PCCES 的資料庫。"
                "請使用者先開一次 PCCES 確認能進預算書（或在 Windows「服務」確認 SQL Server (SQLEXPRESS) 是執行中），再重叫一次。")
    if state in ("28000", "42000"):
        return (f"連得到 SQL Server {server}，但目前的 Windows 帳號進不了 {DATABASE} 資料庫。"
                "請使用者確認這台的 PCCES 用 ConfigEditor 建過 Pcces 資料庫，且安裝 SQL Server 時有按「加入目前使用者」。")
    return f"連 PCCES 資料庫 {server} 失敗。"


def connect():
    """開一條唯讀連線；失敗一律轉成 DbUnavailable。呼叫端要自己 close（pyodbc 的 with 只 commit 不關）。"""
    server = server_name()
    if pyodbc is None:
        raise DbUnavailable("這個環境沒裝 pyodbc，讀不了 PCCES 資料庫；請在專案目錄跑 uv sync 補上。")
    driver = driver_name()
    conn_str = (f"DRIVER={{{driver}}};SERVER={server};DATABASE={DATABASE};"
                "Trusted_Connection=yes;ApplicationIntent=ReadOnly")
    try:
        # autocommit：每句 SELECT 讀完就結束，不留著一個開著的交易
        conn = pyodbc.connect(conn_str, readonly=True, autocommit=True, timeout=LOGIN_TIMEOUT)
    except pyodbc.Error as exc:
        state = str(exc.args[0]) if exc.args else ""
        raise DbUnavailable(f"{_explain(state, server, driver)}（ODBC {state}）") from exc
    conn.timeout = QUERY_TIMEOUT
    return conn


def select(conn, sql: str, *params: Any) -> list[dict[str, Any]]:
    """執行一句 SELECT，回傳欄名對值的 dict 清單。"""
    check_select_only(sql)
    cur = conn.cursor()
    try:
        cur.execute(sql, *params)
        cols = [d[0] for d in cur.description]
        return [dict(zip(cols, r)) for r in cur.fetchall()]
    except pyodbc.Error as exc:
        state = str(exc.args[0]) if exc.args else ""
        raise DbUnavailable(
            f"查詢 PCCES 資料庫失敗（ODBC {state}）：可能是 PCCES 版本不同、資料表欄位不一樣。"
        ) from exc
    finally:
        cur.close()
